sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    try {
        // 1. Initialize your existing REST message and method
        var sm = new sn_ws.RESTMessageV2('Open AI Integration', 'AI Input');

        // Hardened prompt enforcing a predictable JSON structure
        var systemPrompt = "You are an industrial automation parser. Review vault telemetry logs. Respond STRICTLY in valid raw JSON matching this schema: {\"safety_level\":\"CRITICAL\"|\"WARNING\"|\"NORMAL\",\"root_cause\":\"string\",\"remediation\":\"string\",\"pump_override\":true|false}. Do not wrap in markdown or backticks.";

        var userContent = current.description.toString();

        var jsonPayload = {
            "model": "gpt-4o-mini",
            "messages": [
                { "role": "system", "content": systemPrompt },
                { "role": "user", "content": userContent }
            ],
            "temperature": 0.0 // Locked at 0.0 for maximum structural determinism
        };

        sm.setRequestBody(JSON.stringify(jsonPayload));

        // 2. Execute call and benchmark round-trip performance latency
        var startTime = new Date().getTime();
        var response = sm.execute();
        var endTime = new Date().getTime();

        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        // 3. Process response on successful HTTP 200
        if (httpStatus == 200) {
            current.execution_latency = endTime - startTime;
            current.ai_json_output = responseBody;

            // Use standard global JSON engine safely
            var parsedJson = JSON.parse(responseBody);

            if (parsedJson && parsedJson.choices && parsedJson.choices[0]) {
                var aiText = parsedJson.choices[0].message.content;

                // Robust sanitation: Strip markdown code blocks if the LLM leaked them
                aiText = aiText.replace(/```json/g, "").replace(/```/g, "").trim();

                // Safely parse the inner payload
                var analysis = JSON.parse(aiText);

                // 4. Map variables safely using fallback defaults if fields are missing
                var rootCause = analysis.root_cause || "Unknown structural anomaly detected.";
                var remediation = analysis.remediation || "Dispatch field technician for manual check.";
                var pumpOverride = analysis.pump_override !== undefined ? analysis.pump_override : false;
                var safetyLevel = analysis.safety_level || "WARNING";

                // Build clean work notes layout
                current.analysis = "=== AI REAL-TIME ANALYSIS ENGINE ===\n" +
                                     "Safety Assessment: " + safetyLevel + "\n" +
                                     "Root Cause: " + rootCause + "\n" +
                                     "Recommended Mitigation: " + remediation + "\n" +
                                     "Automated Pump Override Active: " + pumpOverride;

                // 5. Execute priority escalation rules based on parsed values
                if (safetyLevel === "CRITICAL") {
                    current.impact = 1;
                    current.urgency = 1; // Pushes to Priority 1
                    if (current.short_description.indexOf("[⚠️ AI ESCALATION]") === -1) {
                        current.short_description = "[⚠️ AI ESCALATION] " + current.short_description;
                    }
                } else if (safetyLevel === "WARNING") {
                    current.urgency = 2; // Medium-high priority
                }

                // Important: Prevent infinite BR recursion loop
                current.setWorkflow(false); 
                current.update();
            } else {
                gs.error("AI Vault Processor: Received empty or malformed payload structure from OpenAI.");
            }
        } else {
            // Safe casting of responseBody to string for log tracking
            gs.error("AI Vault Processor HTTP Error: " + httpStatus + " - " + String(responseBody));
        }
    } catch (ex) {
        gs.error("AI Vault Processor Exception thrown: " + ex.message);
    }
})(current, previous);
